-- Read-only metadata comparison. Use the same session search_path on both sides.
with objects as (
 select 'table' kind, n.nspname||'.'||c.relname||':'||c.relrowsecurity||':'||c.relforcerowsecurity||':'||pg_get_userbyid(c.relowner) body from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('r','p') and n.nspname in ('public','auth','storage','crm_private','supabase_migrations')
 union all select 'constraint',n.nspname||'.'||c.relname||'.'||k.conname||':'||pg_get_constraintdef(k.oid) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth','storage','crm_private','supabase_migrations')
 union all select 'function',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind='f' and n.nspname in ('public','auth','storage','crm_private','supabase_migrations')
 union all select 'trigger',n.nspname||'.'||c.relname||'.'||t.tgname||':'||pg_get_triggerdef(t.oid) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','auth','storage','crm_private','supabase_migrations')
 union all select 'policy',schemaname||'.'||tablename||'.'||policyname||':'||permissive||':'||roles::text||':'||cmd||':'||coalesce(qual,'')||':'||coalesce(with_check,'') from pg_policies where schemaname in ('public','auth','storage','crm_private','supabase_migrations')
 union all select 'grant',n.nspname||'.'||c.relname||':'||case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end||':'||a.privilege_type||':'||a.is_grantable from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where c.relkind in ('r','p') and n.nspname in ('public','auth','storage','crm_private','supabase_migrations')
) select kind,count(*)::int as count,md5(string_agg(body,E'\n' order by body collate "C")) as fingerprint from objects group by kind order by kind;
